export const MAX_LEVEL=50;
export function xpForLevel(level:number){const n=Math.max(0,Math.min(MAX_LEVEL-1,Math.floor(level)-1));return 100*n*n+400*n}
export const MAX_XP=xpForLevel(MAX_LEVEL);
export function levelForXp(xp:number){const x=Math.max(0,Math.min(MAX_XP,Math.floor(xp)));let level=1;while(level<MAX_LEVEL&&xpForLevel(level+1)<=x)level++;return level}
export function addXp(xp:number,amount:number){const next=Math.max(0,Math.min(MAX_XP,Math.floor(xp+(Number.isFinite(amount)?Math.max(0,amount):0))));return {xp:next,level:levelForXp(next)}}
EOF
