import type{PlayerProfile,Settings}from'./types';import{levelForXp,MAX_XP}from'./progression';
export function createProfile(id='local-player'):PlayerProfile{return{id,name:'Player',xp:0,level:1,cosmetics:{ball:'classic-white',trail:'none',hat:null,unlocked:['classic-white']},statistics:{matches:0,wins:0,holes:0,strokes:0,holesInOne:0,playTime:0},settings:{controlScheme:'drag',masterVolume:.8,musicVolume:.65,effectsVolume:.8,cameraSensitivity:1,invertY:false,reducedMotion:false}}}
export function awardXp(p:PlayerProfile,amount:number):PlayerProfile{const xp=Math.min(MAX_XP,Math.max(0,Math.floor(p.xp+Math.max(0,Number.isFinite(amount)?amount:0))));return{...p,xp,level:levelForXp(xp)}}
export function updateSettings(p:PlayerProfile,patch:Partial<Settings>):PlayerProfile{const s={...p.settings,...patch};s.masterVolume=Math.max(0,Math.min(1,s.masterVolume));s.musicVolume=Math.max(0,Math.min(1,s.musicVolume));s.effectsVolume=Math.max(0,Math.min(1,s.effectsVolume));s.cameraSensitivity=Math.max(.1,Math.min(3,s.cameraSensitivity));return{...p,settings:s}}
EOF
