import{createProfile}from'../player/profile';import{levelForXp,MAX_XP}from'../player/progression';import type{PlayerProfile}from'../player/types';
export const SAVE_VERSION=2;export const SAVE_KEY='crazy-putt-arena.save';
export interface StorageLike{getItem(k:string):string|null;setItem(k:string,v:string):void;removeItem(k:string):void}
type R=Record<string,unknown>;const rec=(v:unknown):v is R=>!!v&&typeof v==='object'&&!Array.isArray(v);const num=(v:unknown,d=0)=>typeof v==='number'&&Number.isFinite(v)?v:d;
function normalize(v:unknown):PlayerProfile{const d=createProfile();if(!rec(v))return d;const c=rec(v.cosmetics)?v.cosmetics:{};const st=rec(v.statistics)?v.statistics:{};const se=rec(v.settings)?v.settings:{};const xp=Math.max(0,Math.min(MAX_XP,Math.floor(num(v.xp))));return{id:typeof v.id==='string'?v.id:d.id,name:typeof v.name==='string'?v.name.slice(0,32):d.name,xp,level:levelForXp(xp),cosmetics:{ball:typeof c.ball==='string'?c.ball:d.cosmetics.ball,trail:typeof c.trail==='string'?c.trail:d.cosmetics.trail,hat:typeof c.hat==='string'?c.hat:null,unlocked:Array.isArray(c.unlocked)?c.unlocked.filter((x):x is string=>typeof x==='string'):d.cosmetics.unlocked},statistics:{matches:Math.max(0,Math.floor(num(st.matches))),wins:Math.max(0,Math.floor(num(st.wins))),holes:Math.max(0,Math.floor(num(st.holes))),strokes:Math.max(0,Math.floor(num(st.strokes))),holesInOne:Math.max(0,Math.floor(num(st.holesInOne))),playTime:Math.max(0,Math.floor(num(st.playTime)))},settings:{controlScheme:se.controlScheme==='charge'?'charge':'drag',masterVolume:Math.max(0,Math.min(1,num(se.masterVolume,.8))),musicVolume:Math.max(0,Math.min(1,num(se.musicVolume,.65))),effectsVolume:Math.max(0,Math.min(1,num(se.effectsVolume,.8))),cameraSensitivity:Math.max(.1,Math.min(3,num(se.cameraSensitivity,1))),invertY:se.invertY===true,reducedMotion:se.reducedMotion===true}}}
export function migrateSave(raw:unknown):PlayerProfile{if(!rec(raw))return createProfile();const version=num(raw.version,1);if(version===2)return normalize(raw.profile);if(version===1){const p=rec(raw.profile)?{...raw.profile}: {...raw};if(!('xp'in p)&&typeof raw.xp==='number')p.xp=raw.xp;if(rec(p.settings)&&p.settings.controlScheme==='hold')p.settings={...p.settings,controlScheme:'charge'};return normalize(p)}return createProfile()}
export class SaveManager{constructor(private storage:StorageLike|null=typeof localStorage==='undefined'?null:localStorage,private key=SAVE_KEY){}load(){if(!this.storage)return createProfile();try{const s=this.storage.getItem(this.key);return s?migrateSave(JSON.parse(s)):createProfile()}catch{return createProfile()}}save(p:PlayerProfile){if(!this.storage)return false;try{this.storage.setItem(this.key,JSON.stringify({version:SAVE_VERSION,profile:normalize(p)}));return true}catch{return false}}reset(){try{this.storage?.removeItem(this.key)}catch{}return createProfile()}}
EOF
cat > tests/save-manager.test.ts <<'EOF'
import assert from'node:assert/strict';import test from'node:test';import{SaveManager,SAVE_KEY,migrateSave,type StorageLike}from'../src/core/SaveManager';import{createProfile}from'../src/player/profile';import{levelForXp,MAX_LEVEL,MAX_XP,xpForLevel}from'../src/player/progression';
class Memory implements StorageLike{m=new Map<string,string>();getItem(k:string){return this.m.get(k)??null}setItem(k:string,v:string){this.m.set(k,v)}removeItem(k:string){this.m.delete(k)}}
test('XP spans levels 1-50',()=>{assert.equal(levelForXp(0),1);assert.equal(levelForXp(MAX_XP),MAX_LEVEL);assert.ok(xpForLevel(50)>xpForLevel(49))});
test('round trip',()=>{const s=new Memory(),m=new SaveManager(s);const p=createProfile('p1');p.name='Golfer';p.xp=xpForLevel(8);assert.equal(m.save(p),true);const q=m.load();assert.equal(q.name,'Golfer');assert.equal(q.level,8)});
test('corrupt JSON safely falls back',()=>{const s=new Memory();s.setItem(SAVE_KEY,'{bad');assert.equal(new SaveManager(s).load().level,1)});
test('migrates v1 flat xp and old control name',()=>{const p=migrateSave({version:1,id:'old',name:'Old',xp:xpForLevel(5),settings:{controlScheme:'hold'}});assert.equal(p.level,5);assert.equal(p.settings.controlScheme,'charge')});
test('future version safely falls back',()=>assert.equal(migrateSave({version:999,profile:{xp:MAX_XP}}).level,1));
EOF
